mapper.select:
SELECT COUNT(1) FROM assess_mgmt
WHERE deleted = 0

    AND cycle = #{cycle}


    AND assess_type = #{assessType}


    AND status = #{status}

SELECT AVG(score) FROM assess_mgmt
WHERE deleted = 0

    AND grade = #{grade}


    AND major = #{major}


    AND assess_type = #{assessType}


    AND status = #{status}

SELECT COUNT(1) FROM assess_mgmt
WHERE deleted = 0 AND status = '已发布' AND publish_time >= DATE(NOW()) AND publish_time < DATE(NOW())

    AND grade = #{grade}


    AND major = #{major}

SELECT class_name, ROUND(AVG(CASE WHEN assess_type = 'class_clean' THEN score ELSE NULL END),2) AS classCleanScore, ROUND(AVG(CASE WHEN assess_type = 'morning_exercise' THEN score ELSE NULL END),2) AS morningExerciseScore, ROUND(AVG(CASE WHEN assess_type = 'civilized_class' THEN score ELSE NULL END),2) AS civilClassScore, ROUND(AVG(CASE WHEN assess_type = 'blackboard' THEN score ELSE NULL END),2) AS blackboardScore, ROUND(SUM(score),2) AS totalScore FROM assess_mgmt WHERE deleted = 0
AND cycle = #{cycle}
GROUP BY class_name ORDER BY totalScore DESC

SELECT cycle AS cycleName, ROUND(AVG(score),2) AS avgScore, create_time, rank_no AS rankNo FROM assess_mgmt WHERE deleted = 0
AND class_name = #{className}
GROUP BY cycle, create_time, rank_no ORDER BY cycle, create_time

SELECT AVG(score) FROM assess_mgmt
WHERE deleted = 0

    AND cycle = #{cycle}


    AND status = #{status}

SELECT class_name FROM assess_mgmt
WHERE deleted = 0

    AND cycle = #{cycle}


    AND status = #{status}

ORDER BY score DESC
LIMIT 1

SELECT assess_type, COUNT(1) AS count FROM assess_mgmt
WHERE deleted = 0

    AND cycle = #{cycle}


    AND status = #{status}

GROUP BY assess_type

SELECT status, COUNT(1) AS count FROM assess_mgmt WHERE deleted = 0
AND cycle = #{cycle}
GROUP BY status

SELECT
cycle,
ROUND(AVG(score),2) AS score
FROM assess_mgmt
WHERE deleted = 0

    AND cycle = #{cycle}


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

GROUP BY cycle
